import {stops,kindLabels,optionsFor} from './chapter.mjs';
import {maxHp,maxEnergy} from './combat.mjs';
export function chapterProgress(s){const r=s.journey?.route;if(!r)return '';const remaining=Math.max(0,r.total-r.used);return `<section class="chapter-route"><div class="route-heading"><span>CHAPTER 01 · 제한된 여정</span><strong>${r.ended?'챕터 '+(r.ended==='victory'?'완료':'실패'):remaining?'보스까지 중간 선택 '+remaining+'회':'다음은 마지막 보스'}</strong></div><div class="route-track">${stops.map((stop,i)=>{const entry=r.history.find(h=>h.step===i+1);const active=!r.ended&&((r.current?.step===i+1)||(!r.current&&r.used===i));return `<div class="route-stop ${i<r.used?'used':''} ${active?'current':''}" title="${stop.name}"><span>${i<r.used?'✓':i+1}</span><small>${entry?kindLabels[entry.kind]:stop.name}</small></div>`;}).join('')}<div class="route-stop boss ${r.ended?'used':r.used>=r.total&&!r.current?'current':''}"><span>終</span><small>마지막 보스</small></div></div><p>${r.ended?'이 도전에서 더 이상 전투·휴식·방문을 반복할 수 없습니다.':r.current&&r.current.kind!=='boss'?'이번 장소에 여정 1칸을 이미 사용했습니다. 방문을 마치면 다음 갈림길로 갑니다.':r.used>=r.total?'중간 선택을 모두 마쳤습니다. 소모품과 장착을 확인한 뒤 마지막 보스로 향하세요.':'장소 하나를 고르면 여정 1칸을 씁니다. 장착과 얻은 성장점 배분은 무료입니다.'}</p></section>`;}
export function routeCards(s){if(!['hub','map'].includes(s.scene))return '';const r=s.journey.route;
 if(r.ended)return `<div class="chapter-conclusion"><p class="eyebrow">${r.ended==='victory'?'CHAPTER COMPLETE':'CHAPTER ENDED'}</p><h3>${r.ended==='victory'?'여섯 선택이 만든 결말':'선택을 바꾸어 다시 도전할 수 있다'}</h3><p>다시 도전하면 이 챕터를 시작했던 능력과 소지품으로 돌아갑니다. 이번에 얻은 경험·장비·재화는 누적되지 않습니다.</p></div>`;
 if(r.used>=r.total)return `<div class="boss-gate"><img src="assets/combat/leader.png" alt="마지막 길을 지키는 봉쇄대의 우두머리"><div><p class="eyebrow">FINAL ENCOUNTER</p><h3>봉쇄대의 우두머리</h3><p>두 공방마다 강한 공격. 세 공방마다 반격을 준비합니다.</p><p>${r.intel.includes('read-pattern')?'정찰자의 정보로 강한 공격의 추가 위력이 1 줄었습니다.':'휴식·상점·전투를 더 고를 기회는 없습니다.'}</p><strong>남은 준비를 마치고 마지막 전투로 향하세요.</strong></div></div>`;
 return `<div class="route-options">${optionsFor(s).map(o=>{const disabled=o.kind==='rest'&&s.hp>=maxHp(s)&&s.energy>=maxEnergy(s);return `<button class="route-option" data-choice="node-${o.id}" ${disabled?'disabled':''}><div class="route-option-art"><img src="assets/${o.image}.png" alt=""><span>${kindLabels[o.kind]}</span></div><div class="route-option-copy"><small>여정 1칸</small><h3>${o.name}</h3><p>${o.hint}</p><strong>${disabled?'이미 체력과 숨이 가득합니다':'이 길을 선택한다 →'}</strong></div></button>`;}).join('')}</div>`;
}
